fun Cocktail_Shaker_Sort(@init<table> array):
    n = length(array)

    // Set lower and upper bounds for the range of unsorted elements
    lower = 0
    upper = n - 1

    // Continue sorting while there are elements to sort
    while (lower < upper):
        swapped = False

        // Pass from left to right
        @mark<lower, outline, yellow> for (i = lower, i < upper, i += 1):
            @mark<i, outline, yellow> if (array[i] > array[i + 1]):
                @mark<i, highlight, green> swap(array[i], array[i + 1])
                swapped = True
            end if
        end for

        // After left-to-right pass, the largest element is at the end
        upper -= 1

        if (swapped == False):
            break
        end if

        // Pass from right to left
        @mark<upper, outline, yellow> for (i = upper, i > lower, i -= 1):
            @mark<i, outline, yellow> if (array[i] < array[i - 1]):
                @mark<i, highlight, green> swap(array[i], array[i - 1])
                swapped = True
            end if
        end for

        // After right-to-left pass, the smallest element is at the beginning
        lower += 1

        if (swapped == False):
            break
        end if
    end while

    return array
end fun

