fun Dutch_National_Flag_Sort(@init<table> array):
    n = length(array)

    // Three pointers: low for 0s, mid for 1s, high for 2s
    low = 0
    mid = 0
    high = n - 1

    // Traverse the array from start to end
    while (mid <= high):
        @mark<mid, outline, yellow> if (array[mid] == 0):
            // Swap current element with element at low pointer
            @mark<low, highlight, green> swap(array[low], array[mid])
            low += 1
            mid += 1
        else if (array[mid] == 1):
            // 1s are already in correct place, move mid pointer
            mid += 1
        else:
            // Swap current element with element at high pointer
            @mark<high, highlight, green> swap(array[mid], array[high])
            high -= 1
            // Do not increment mid here because swapped element from high hasn't been checked yet
        end if
    end while

    return array
end fun

