fun Boyer_Moore_Majority_Element(@init<table> nums):
    n = length(nums)

    // Phase 1: Voting
    candidate = nums[0]
    count = 1

    for (i = 1; i < n; i += 1):
        @mark<i, outline, yellow> if (nums[i] == candidate):
            @mark<i, highlight, green> count += 1
        end if

        @mark<i, outline, yellow> if (nums[i] != candidate):
            @mark<i, highlight, red> count -= 1

            if (count == 0):
                @mark<i, highlight, green> candidate = nums[i]
                @mark<i, highlight, green> count = 1
            end if
        end if
    end for

    // Phase 2: Verification
    verify_count = 0
    for (i = 0; i < n; i += 1):
        @mark<i, outline, yellow> if (nums[i] == candidate):
            @mark<i, highlight, green> verify_count += 1
        end if
    end for

    // Check if candidate appears more than n/2 times
    if (verify_count > floor(n / 2)):
        @log<info, "Majority element found"> return candidate
    end if

    @log<warn, "No majority element"> return -1
end fun

