    // Initialize min and max with first two elements
    @mark<0, outline, yellow> @mark<1, outline, yellow> if (array[0] > array[1]):
        @mark<0, highlight, green> max = array[0]
        @mark<1, highlight, green> min = array[1]
    else:
        @mark<1, highlight, green> max = array[1]
        @mark<0, highlight, green> min = array[0]
