            @mark<i, highlight, green> candidate_min = array[i]
        end if

        // Update global min and max
        @mark<i, text, fg> if (candidate_max > max):
            @mark<i, highlight, green> max = candidate_max
        end if

        @mark<i, text, fg> if (candidate_min < min):
            @mark<i, highlight, green> min = candidate_min
        end if

        i += 2
