        @mark<i, outline, yellow> @mark<i, text, fg> if (array[i] > max):
            @mark<i, highlight, green> max = array[i]
        end if

        @mark<i, text, fg> if (array[i] < min):
            @mark<i, highlight, green> min = array[i]
        end if
    end if

    result = arr[min, max]
