fun Odd_Even_Transposition_Sort(@init<table> array):
    n = length(array)

    // Continue sorting while the array is not fully sorted
    sorted = false
    while (not sorted):
        sorted = true

        // Odd phase: compare elements at odd indices
        for (i = 1; i < n - 1; i += 2):
            @mark<i, outline, yellow> if (array[i] > array[i + 1]):
                @mark<i, highlight, green> swap(array[i], array[i + 1])
                sorted = false
            end if
        end for

        // Even phase: compare elements at even indices
        for (i = 0; i < n - 1; i += 2):
            @mark<i, outline, yellow> if (array[i] > array[i + 1]):
                @mark<i, highlight, green> swap(array[i], array[i + 1])
                sorted = false
            end if
        end for
    end while

    return array
end fun

