fun Quickselect(@init<table> array, low, high, k):
    // Base case: if low equals high, we've found our element
    if (low == high):
        @mark<low, highlight, green> return array[low]
    end if

    // Partition the array and get pivot index
    @mark<low, outline, yellow> @mark<high, outline, yellow> pivot_index = Lomuto_Partition(array, low, high)

    // If pivot is the k-th smallest element, return it
