    end if

    // If k-th element is in left subarray
    @mark<pivot_index, text, fg> if (pivot_index > k - 1):
        @mark<pivot_index, outline, yellow> return Quickselect(array, low, pivot_index - 1, k)
    end if

    // If k-th element is in right subarray
    @mark<pivot_index, outline, yellow> return Quickselect(array, pivot_index + 1, high, k)

