fun Remove_Duplicates(@init<table> array):
    n = length(array)

    // Handle edge case of empty array
    if (n == 0):
        return 0
    end if

    // Index for the position of unique elements
    @mark<i, outline, yellow> i = 0

    // Traverse the array starting from second element
    for (j = 1; j < n; j += 1):
        // If current element is different from previous,
        // it's a new unique element
        @mark<j, outline, yellow> if (array[j] != array[i]):
            @mark<j, highlight, green> i += 1
            @mark<i, highlight, green> swap(array[i], array[j])
        end if
    end for

    // Return count of unique elements (i+1 since index starts at 0)
    return i + 1
end fun

