fun Shell_Sort(@init<table> array):
    n = length(array)

    // Start with a large gap, then reduce the gap
    gap = floor(n / 2)

    // Continue until gap becomes 0
    while (gap > 0):
        // Do a gapped insertion sort for this gap size
        for (i = gap, i < n, i += 1):
            @mark<i, outline, yellow> temp = array[i]

            // Shift earlier gap-sorted elements up until the correct location for array[i] is found
            j = i
            @mark<j, text, fg> while (j >= gap and array[j - gap] > temp):
                @mark<j, highlight, green> array[j] = array[j - gap]
                j -= gap
            end while

            // Put temp (the original array[i]) in its correct location
            @mark<j, highlight, green> array[j] = temp
        end for

        // Reduce the gap for the next iteration
        gap = floor(gap / 2)
    end while

    return array
end fun

