fun Two_Sum(@init<table> array, target):
    // Initialize two pointers at the start and end of the array
    left = 0
    right = length(array) - 1

    // Loop while the pointers haven't met
    while (left < right):
        // Calculate the sum of values at the two pointers
        @mark<left, outline, yellow> @mark<right, outline, yellow> currentSum = array[left] + array[right]

        // If the sum equals the target, we found our pair
        if (currentSum == target):
            @log<info, "Pair found"> result = arr[left, right]
            return result
        end if

        // If the sum is less than target, move left pointer right
        if (currentSum < target):
            @mark<left, highlight, green> left += 1
        else:
            // Else the sum is greater than target, move right pointer left
            @mark<right, highlight, green> right -= 1
        end if
    end while

    // No pair found, return [-1, -1]
    @log<info, "No pair found"> result = arr[-1, -1]
    return result
end fun

