fun Two_Sum(@init<table> array, target):
    // Initialize two pointers at both ends of the array
    left = 0
    right = length(array) - 1

    // Loop while pointers haven't crossed
    while (left < right):
        // Calculate sum of values at the two pointers
        @mark<left, outline, yellow> @mark<right, outline, yellow> currentSum = array[left] + array[right]

        // If sum equals target, we found our pair
        if (currentSum == target):
            @log<info, "Pair found"> result = arr[left, right]
            return result
        end if

        // If sum is less than target, move left pointer right to increase sum
        if (currentSum < target):
            @mark<left, highlight, green> left += 1
        else:
            // If sum is greater than target, move right pointer left to decrease sum
            @mark<right, highlight, green> right -= 1
        end if
    end while

    // No valid pair found
    @log<info, "No pair found"> result = arr[-1, -1]
    return result
end fun

